package net.minecraft.world.item.crafting;import net.minecraft.world.item.*;import net.minecraft.world.inventory.*;import net.minecraft.resources.*;import net.minecraft.core.*;public class CraftingRecipe {public ResourceLocation getId(){return new ResourceLocation("minecraft:torch_recipe");}public ItemStack assemble(CraftingContainer c,Object registry){return new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get("minecraft:torch"),4);}public NonNullList<ItemStack> getRemainingItems(CraftingContainer c){NonNullList<ItemStack> result=new NonNullList<>();for(int i=0;i<9;i++)result.add(ItemStack.EMPTY);return result;}}
